  var dirFn = function (d) { state.dir = d; state.frame = 0; buttonRow(dirs, ['N', 'E', 'S', 'W'], state.dir, dirFn); draw(); };
  buttonRow(dirs, ['N', 'E', 'S', 'W'], state.dir, dirFn);
